"""The ``pennywise`` command."""

from __future__ import annotations

import argparse
import csv
import io
import json
import os
import sys
from typing import List, Optional, Sequence

from .core import (
    Entry,
    ParseError,
    _parse_date,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_line,
)

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _ReadError(Exception):
    pass


def _date_arg(text: str):
    d = _parse_date(text)
    if d is None:
        raise argparse.ArgumentTypeError(f"invalid date {text!r} (expected YYYY-MM-DD)")
    return d


def _read_ledger(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as f:
                data = f.read()
        return data.decode("utf-8-sig")
    except OSError as exc:
        raise _ReadError(f"cannot read {path}: {exc.strerror or exc}") from exc
    except UnicodeDecodeError as exc:
        raise _ReadError(f"cannot read {path}: not valid UTF-8 text") from exc


def _load(path: str) -> List[Entry]:
    return parse(_read_ledger(path))


def _sorted(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same-day keeps file order


def _entry_json(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _emit(text: str) -> None:
    sys.stdout.write(text)


def cmd_balance(args) -> int:
    total = balance(_load(args.file))
    if args.json:
        _emit(json.dumps({"balance": format_amount(total)}) + "\n")
    else:
        _emit(format_amount(total) + "\n")
    return EXIT_OK


def cmd_summary(args) -> int:
    entries = _load(args.file)
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    if args.json:
        _emit(json.dumps({k: format_amount(v) for k, v in groups.items()}) + "\n")
    else:
        _emit("".join(f"{k}  {format_amount(v)}\n" for k, v in groups.items()))
    return EXIT_OK


def cmd_list(args) -> int:
    entries = _sorted(
        filter_entries(_load(args.file), category=args.category, since=args.since, until=args.until)
    )
    if args.json:
        _emit(json.dumps([_entry_json(e) for e in entries]) + "\n")
    else:
        _emit("".join(format_entry(e) + "\n" for e in entries))
    return EXIT_OK


def cmd_export(args) -> int:
    entries = _sorted(_load(args.file))
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    _emit(buf.getvalue())
    return EXIT_OK


def _line_count(path: str) -> int:
    """Number of the line a newly appended entry will occupy."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except FileNotFoundError:
        return 1
    except OSError as exc:
        raise _ReadError(f"cannot read {path}: {exc.strerror or exc}") from exc
    if not data:
        return 1
    n = data.count(b"\n")
    return n + 1 if data.endswith(b"\n") else n + 2


def cmd_add(args) -> int:
    path = args.file
    lineno = _line_count(path)
    fields = [args.date, args.category, args.amount]
    note = args.note if args.note is not None else ""
    for field in fields:
        if field == "" or any(c.isspace() for c in field):
            raise ParseError(lineno, f"invalid field {field!r}")
    if "\n" in note or "\r" in note or len(note.splitlines()) > 1:
        raise ParseError(lineno, "note must be a single line")
    raw = " ".join(fields + ([note] if note.strip() else []))
    entry = parse_line(raw, lineno)
    if entry is None:  # e.g. date field starting with '#'
        raise ParseError(lineno, f"invalid date {args.date!r}")
    line = format_entry(entry)

    try:
        with open(path, "a+b") as f:
            f.seek(0, os.SEEK_END)
            prefix = b""
            if f.tell() > 0:
                f.seek(-1, os.SEEK_END)
                if f.read(1) != b"\n":
                    prefix = b"\n"
                f.seek(0, os.SEEK_END)
            f.write(prefix + line.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _ReadError(f"cannot write {path}: {exc.strerror or exc}") from exc
    _emit(line + "\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell you where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def ledger_cmd(name, help_text, func, json_flag=True):
        p = sub.add_parser(name, help=help_text, description=help_text)
        p.add_argument("file", metavar="FILE", help="ledger file ('-' for standard input)")
        if json_flag:
            p.add_argument("--json", action="store_true", help="print JSON")
        p.set_defaults(func=func)
        return p

    ledger_cmd("balance", "print the total of all amounts", cmd_balance)

    p = ledger_cmd("summary", "print totals per category or month", cmd_summary)
    p.add_argument("--by", choices=["category", "month"], default="category")

    p = ledger_cmd("list", "print matching entries, oldest first", cmd_list)
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)

    p = ledger_cmd("export", "print entries as CSV", cmd_export, json_flag=False)
    p.add_argument("--format", choices=["csv"], default="csv")

    p = sub.add_parser("add", help="append an entry to the ledger", description="append an entry")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?")
    p.set_defaults(func=cmd_add)
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:  # argparse: --help exits 0, errors exit 2
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE
    try:
        return args.func(args)
    except ParseError as exc:
        where = "entry" if args.command == "add" else args.file
        if where == "-":
            where = "<stdin>"
        print(f"pennywise: {where}: {exc}", file=sys.stderr)
        return EXIT_LEDGER
    except _ReadError as exc:
        print(f"pennywise: {exc}", file=sys.stderr)
        return EXIT_USAGE
    except BrokenPipeError:
        try:
            sys.stdout = open(os.devnull, "w")
        except OSError:
            pass
        return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
